import React, { useEffect, useRef, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { motion } from 'framer-motion';
import { Chess } from 'chess.js';
import { ChessgroundBoard as Chessboard } from './ui/ChessgroundBoard';
import Peer, { type DataConnection } from 'peerjs';
import { create } from 'zustand';
import { calibrateRating, openingsUnlocked, penalizeCct, useHint, type ErrorTag, type TrainingState, recordGame, recordPuzzle, recordVision } from './training/model';
import { addPuzzleAttempt, loadTraining, saveTraining } from './storage/local';
import { puzzleFor } from './training/puzzles';
import { chooseDuePuzzle, loadPuzzleCatalog, quickCalibration } from './training/catalog';
import { matchesPuzzleMove, type PreparedPuzzle } from './training/lichess';
import { validateCct } from './training/cct';
import { addCctAttempt } from './storage/local';
import { EngineClient } from './engine/client';
import { mateLibrary, mateThemes, type MateTheme } from './training/mates';
import { loadOpenings, searchOpenings, type Opening } from './training/openings';
import { phaseNames, trainingPath } from './training/path';
import { localPeerConfig, peerUnavailableMessage } from './social/peerConfig';
import { saveGameRecord } from './social/gameRecord';
import { loadGameRecords } from './social/gameRecord';
