import './styles.css';

type Tab = 'overview'|'path'|'lesson'|'diagnosis'|'train'|'vision'|'mates'|'openings'|'studio'|'invite'|'play'|'journal';
type Scan = { checks:boolean; captures:boolean; threats:boolean };
type Store = { tab:Tab; lessonId:string; setTab:(tab:Tab)=>void; openLesson:(id:string)=>void; training:TrainingState; scans:Scan; candidate:string; setCandidate:(candidate:string)=>void; setScan:(key:keyof Scan)=>void; resetScan:()=>void; completeScan:()=>void; calibrate:(correct:number)=>void; recordPuzzleAttempt:(solved:boolean,puzzleId:string,rating:number,move?:string)=>void; recordGameOutcome:(tag?:ErrorTag)=>void; recordVisionAttempt:(correct:boolean)=>void; recordCctFailure:()=>void; useHint:(level:1|2)=>void };
const useStore = create<Store>((set)=>({tab:'overview',lessonId:'board',setTab:(tab)=>set({tab}),openLesson:(lessonId)=>set({lessonId,tab:'lesson'}),training:loadTraining(),scans:{checks:false,captures:false,threats:false},candidate:'',setCandidate:(candidate)=>set({candidate}),setScan:(key)=>set(s=>({scans:{...s.scans,[key]:!s.scans[key]}})),resetScan:()=>set({scans:{checks:false,captures:false,threats:false},candidate:''}),completeScan:()=>set(s=>({scans:{checks:false,captures:false,threats:false},candidate:'',tab:'overview'})),calibrate:(correct)=>set(s=>{const next={...s.training,rating:calibrateRating(correct)};saveTraining(next);return {training:next}}),recordPuzzleAttempt:(solved,puzzleId,rating,move)=>set(s=>{const next=recordPuzzle(s.training,solved); const card=s.training.reviews[puzzleId]; const review={...scheduleReview(card,solved),puzzleId}; const saved={...next,reviews:{...next.reviews,[puzzleId]:review}};saveTraining(saved);void addPuzzleAttempt({puzzleId,solved,rating,move,createdAt:new Date().toISOString()});return {training:saved}}),recordGameOutcome:(tag)=>set(s=>{const next=recordGame(s.training,tag);saveTraining(next);return {training:next}}),recordVisionAttempt:(correct)=>set(s=>{const next=recordVision(s.training,correct);saveTraining(next);return {training:next}}),recordCctFailure:()=>set(s=>{const next=penalizeCct(s.training);saveTraining(next);return {training:next}}),useHint:(level)=>set(s=>{const next=useHint(s.training,level);saveTraining(next);return {training:next}})}));

const nav = [{id:'overview' as Tab, label:'Resumen', icon:'▦'},{id:'path' as Tab,label:'Camino',icon:'◇'},{id:'diagnosis' as Tab,label:'Diagnóstico',icon:'◎'},{id:'train' as Tab,label:'Entrenar',icon:'⌁'},{id:'vision' as Tab,label:'Visión',icon:'◌'},{id:'mates' as Tab,label:'Mates',icon:'♔'},{id:'openings' as Tab,label:'Aperturas',icon:'⌂'},{id:'studio' as Tab,label:'Estudio',icon:'▣'},{id:'invite' as Tab,label:'Invitar',icon:'↗'},{id:'play' as Tab,label:'Jugar',icon:'♞'},{id:'journal' as Tab,label:'Diario',icon:'↗'}];
const themes = ['Pieza colgada','Amenaza no vista','Mate fallado','Cambio mal calculado'];

function App(){ const {tab,setTab}=useStore(); return <div className="app"><aside className="sidebar"><div className="brand"><span className="mark">G</span><span>GOD<span className="muted">CHESS</span></span></div><div className="profile"><div className="avatar">J</div><div><strong>Jugador local</strong><small>Explorador · 200 ELO</small></div></div><nav>{nav.map(n=><button className={tab===n.id?'active':''} onClick={()=>setTab(n.id)} key={n.id}><span>{n.icon}</span>{n.label}{n.id==='train'&&<b>3</b>}</button>)}</nav><div className="sidebar-foot"><span className="status-dot"/>Motor local listo<small>Sincronización privada</small></div></aside><main><header><div><span className="eyebrow">JUEVES · 26 NOVIEMBRE 2026</span><h1>{tab==='overview'?'Tu siguiente error es el entrenamiento.':tab==='train'?'Sesión dirigida':'Tu espacio de práctica'}</h1></div><button className="icon-button" aria-label="Ajustes">⚙</button></header>{tab==='overview'?<Overview/>:tab==='path'?<Path/>:tab==='lesson'?<GuidedLesson/>:tab==='diagnosis'?<DiagnosisReal/>:tab==='train'?<Train/>:tab==='vision'?<Vision/>:tab==='mates'?<Mates/>:tab==='openings'?<OpeningsV2/>:tab==='studio'?<Studio/>:tab==='invite'?<InviteV2/>:tab==='play'?<Play/>:<Journal/>}</main></div> }

function Overview(){const {training}=useStore(); const accuracy=training.puzzleAttempts?training.visionAccuracy:0; const pieces=training.games?((training.errors['pieza colgada']/training.games).toFixed(1)):'0.0'; const focusCount=training.errors['pieza colgada']; return <div className="page"><section className="hero-grid"><div className="hero-card"><div className="hero-copy"><span className="tag">FASE 0 · VISIÓN Y SEGURIDAD</span><h2>Hoy: ver la amenaza<br/>antes de mover.</h2><p>Tu patrón dominante esta semana es <strong>pieza colgada</strong>. El plan de hoy empieza con 3 escaneos CCT y termina en una partida lenta.</p><button className="primary" onClick={()=>useStore.getState().setTab('train')}>Empezar sesión <span>→</span></button></div><div className="ring"><strong>{training.puzzleSolved}</strong><span>puzzles resueltos</span></div></div><aside className="streak"><span className="eyebrow">PROGRESO LOCAL</span><strong>{training.xp} <small>XP</small></strong><div className="days"><i>{training.puzzleAttempts}</i><i>{training.puzzleSolved}</i><i className="today">{accuracy}%</i><i className="empty">—</i><i className="empty">—</i><i className="empty">—</i><i className="empty">—</i></div><p>Los datos se quedan en este dispositivo.</p></aside></section><section className="section-head"><div><span className="eyebrow">PULSO DE PROGRESO</span><h3>Errores que estás dejando atrás</h3></div><span className="range">Datos persistidos⌄</span></section><section className="metrics"><Metric label="Piezas colgadas" value={pieces} delta="perfil local" note="por partida" good/><Metric label="Errores graves" value={training.games?String((Object.values(training.errors).reduce((a,b)=>a+b,0)/training.games).toFixed(1)):'0.0'} delta="perfil local" note="por partida" good/><Metric label="Precisión de puzzles" value={`${accuracy}%`} delta={`${training.puzzleSolved}/${training.puzzleAttempts}`} note="resueltos" good/><Metric label="Partidas lentas" value={String(training.slowGames)} delta="objetivo 20" note="para desbloquear aperturas"/></section><section className="lower-grid"><div className="focus-panel"><div className="section-head"><div><span className="eyebrow">FOCO AUTOMÁTICO</span><h3>Tu semana en una línea</h3></div><span className="signal">● ACTIVO</span></div><div className="focus-line"><div className="focus-icon">♟</div><div><strong>Seguridad de piezas</strong><p>El foco se adapta al perfil persistido.</p></div><span className="weight">{focusCount} errores</span></div><div className="bar"><i style={{width:`${Math.min(100,focusCount*10)}%`}}/></div><div className="mini-themes">{themes.slice(1).map((x)=><div key={x}><span>{x}</span><b>pendiente</b></div>)}</div></div><div className="invite-panel"><span className="eyebrow">APRENDER JUNTOS</span><h3>Invita a alguien<br/>a tu tablero.</h3><p>Una partida lenta o una lección de tu plan. Sin cuenta, sin fricción.</p><button className="outline">Crear invitación <span>↗</span></button></div></section></div>}
function Lesson(){const {lessonId,setTab}=useStore();const unit=trainingPath.find(item=>item.id===lessonId)??trainingPath[0];const positions:Record<string,string>={board:'start',pawn:'rnbqkbnr/pppppppp/8/8/4P3/8/PPPP1PPP/RNBQKBNR b KQkq - 0 1',rook:'r3k2r/ppp2ppp/2np1n2/8/8/2NP1N2/PPP2PPP/R3K2R w KQkq - 0 1',bishop:'r3k2r/ppp2ppp/2np1n2/3b4/4B3/2NP1N2/PPP2PPP/R3K2R w KQkq - 0 1',knight:'r1bqk2r/pppp1ppp/2n2n2/4p3/4P3/2N2N2/PPPP1PPP/R1BQKB1R w KQkq - 2 4',queen:'r3k2r/ppp2ppp/2np1n2/3b4/4Q3/2NP1N2/PPP2PPP/R3K2R w KQkq - 0 1',king:'7k/8/8/3pP3/3K4/8/8/8 w - - 0 1'};const fen=positions[unit.id]??'start';return <div className="page lesson-page"><span className="tag">LECCIÓN · FASE {unit.phase}</span><h2>{unit.title}<br/><em>aprende haciendo.</em></h2><p className="instruction">{unit.description}</p><div className="lesson-layout"><div className="real-board lesson-board"><Chessboard animationDuration={250} position={fen} arePiecesDraggable={false} boardWidth={Math.min(520,typeof window==='undefined'?520:window.innerWidth*0.48)} customDarkSquareStyle={{backgroundColor:'#668078'}} customLightSquareStyle={{backgroundColor:'#d9dfd5'}}/></div><div className="diagnosis-card lesson-card"><div className="diagnosis-count"><strong>1</strong><span>/ 3</span></div><div><span className="eyebrow">CONCEPTO CLAVE</span><h3>Observa, nombra y después prueba</h3><p className="instruction">Primero identifica la pieza y su movimiento en el tablero. Después continúa con el ejercicio dirigido.</p></div></div></div><button className="primary" onClick={()=>setTab(unit.kind==='opening'?'openings':unit.kind==='game'?'play':'train')}>Practicar ahora <span>→</span></button></div>}
function Path(){return <div className="page path-page"><span className="tag">CAMINO DE ENTRENAMIENTO · 200 → MÁXIMO</span><h2>Una jugada cada día.<br/><em>Un camino que recuerda.</em></h2><p className="instruction">Las aperturas están todas disponibles en el explorador. El camino decide cuándo conviene estudiarlas, según tu progreso y tus errores.</p>{phaseNames.map((phase,phaseIndex)=><section className="path-phase" key={phase}><div className="section-head"><div><span className="eyebrow">FASE {phaseIndex}</span><h3>{phase}</h3></div><span className="range">{trainingPath.filter(unit=>unit.phase===phaseIndex).length} unidades</span></div><div className="path-units">{trainingPath.filter(unit=>unit.phase===phaseIndex).map((unit,index)=><button className={'path-unit '+(index===0&&phaseIndex===0?'current':'locked')} key={unit.id} onClick={()=>unit.kind==='opening'?useStore.getState().setTab('openings'):unit.kind==='puzzle'||unit.kind==='drill'?useStore.getState().setTab('train'):unit.kind==='game'?useStore.getState().setTab('play'):useStore.getState().openLesson(unit.id)}><span className="path-node">{index===0&&phaseIndex===0?'▶':'·'}</span><span><strong>{unit.title}</strong><small>{unit.description}</small></span><em>{unit.kind}</em></button>)}</div></section>)}</div>}

function Diagnosis(){const [step,setStep]=useState(0); const [correct,setCorrect]=useState(0); const {setTab,calibrate}=useStore(); const prompts=['¿Ves un jaque en una jugada?','¿Qué pieza está indefensa?','¿Cuál es la amenaza rival?','¿Puedes dar mate en uno?','¿Qué captura gana material?','¿Tu rey puede enrocar?']; const answer=(value:boolean)=>{const next=correct+(value?1:0);setCorrect(next);setStep(Math.min(6,step+1));if(step===5)calibrate(next)}; return <div className="page diagnosis"><span className="tag">CALIBRACIÓN · 6 EJERCICIOS</span><h2>Primero medimos.<br/><em>Después entrenamos.</em></h2><p className="instruction">Cada respuesta ajusta tu rating interno. No buscamos conocimiento memorizado: medimos visión, seguridad y cálculo.</p>{step<6?<div className="diagnosis-card"><div className="diagnosis-count"><strong>{step+1}</strong><span>/ 6</span></div><div><span className="eyebrow">EJERCICIO {step+1}</span><h3>{prompts[step]}</h3><div className="answer-grid"><button onClick={()=>answer(true)}>Sí, lo veo</button><button onClick={()=>answer(false)}>Necesito pensarlo</button></div></div></div>:<><div className="diagnosis-card"><div className="diagnosis-count"><strong>{correct}</strong><span>/ 6</span></div><div><span className="eyebrow">CALIBRACIÓN COMPLETA</span><h3>Tu rating interno está listo.</h3><p className="instruction">El plan se adaptará a tus errores, no al contenido consumido.</p></div></div><button className="primary" onClick={()=>setTab('train')}>Empezar plan dirigido <span>→</span></button></>}</div>}
function HintPanel(){const [level,setLevel]=useState(0);const spend=useStore(s=>s.useHint);return <div className="hint-panel"><span className="eyebrow">PISTA PROGRESIVA</span>{level===0&&<button className="outline" onClick={()=>{setLevel(1);spend(1)}}>Pista 1 · ver el motivo</button>}{level===1&&<><p className="instruction">Empieza por enumerar todos tus jaques y capturas antes de buscar una jugada tranquila.</p><button className="outline" onClick={()=>{setLevel(2);spend(2)}}>Pista 2 · reducir opciones</button></>}{level===2&&<p className="instruction">Compara primero las jugadas que obligan una respuesta del rival.</p>}</div>}
function CctInputs({fen,onValid}:{fen:string;onValid:()=>void}){const [answers,setAnswers]=useState({checks:'',captures:'',threats:''});const [message,setMessage]=useState('');const fail=useStore(s=>s.recordCctFailure);const validate=()=>{const parsed={checks:answers.checks.split(/[\s,]+/).filter(Boolean),captures:answers.captures.split(/[\s,]+/).filter(Boolean),threats:answers.threats.split(/[\s,]+/).filter(Boolean)};const result=validateCct(fen,parsed);void addCctAttempt({puzzleId:fen.slice(0,12),valid:result.valid,...parsed,createdAt:new Date().toISOString()});if(result.valid){setMessage('Escaneo correcto · tablero listo');onValid()}else{setMessage('Escaneo incompleto · penalización doble aplicada');fail()}};return <div className="cct-inputs"><label>JAQUES <input value={answers.checks} onChange={e=>setAnswers(v=>({...v,checks:e.target.value}))} placeholder="e2e4"/></label><label>CAPTURAS <input value={answers.captures} onChange={e=>setAnswers(v=>({...v,captures:e.target.value}))} placeholder="b1c3"/></label><label>AMENAZAS <input value={answers.threats} onChange={e=>setAnswers(v=>({...v,threats:e.target.value}))} placeholder="pieza atacada"/></label><button className="outline full" onClick={validate}>Validar escaneo</button>{message&&<p className="board-message">{message}</p>}</div>}
function DiagnosisReal(){const [puzzles,setPuzzles]=useState<PreparedPuzzle[]>(quickCalibration());const [step,setStep]=useState(0);const [correct,setCorrect]=useState(0);const [answer,setAnswer]=useState('');const [feedback,setFeedback]=useState('');const [started]=useState(Date.now());const {setTab,calibrate}=useStore();useEffect(()=>{loadPuzzleCatalog().then(rows=>{const catalog=rows.filter(row=>row.solutionUci.length>0).slice(0,6);if(catalog.length===6)setPuzzles(catalog)}).catch(()=>undefined)},[]);const current=puzzles[step];const submit=()=>{if(!current||!answer.trim())return;const solved=matchesPuzzleMove(answer.trim(),current)||current.solutionSan[0]===answer.trim();const next=correct+(solved?1:0);setCorrect(next);setFeedback(solved?'Correcto · respuesta registrada':'No coincide · se registra como error');setAnswer('');window.setTimeout(()=>{setFeedback('');if(step===5){calibrate(next);setStep(6)}else setStep(value=>value+1)},700)};if(step>=6)return <div className="page diagnosis"><span className="tag">CALIBRACIÓN COMPLETA</span><h2>Tu rating interno<br/><em>ya está listo.</em></h2><div className="diagnosis-card"><div className="diagnosis-count"><strong>{correct}</strong><span>/ 6</span></div><div><span className="eyebrow">RESULTADO</span><h3>Plan adaptativo activado</h3><p className="instruction">Tus próximos puzzles y la fuerza del motor se ajustarán a este resultado.</p></div></div><button className="primary" onClick={()=>setTab('train')}>Empezar plan dirigido <span>→</span></button></div>;if(!current)return <div className="page diagnosis"><span className="tag">CALIBRACIÓN · CARGANDO</span><h2>Preparando tus<br/><em>seis posiciones.</em></h2><p className="instruction">Leyendo el índice local de Lichess…</p></div>;return <div className="page diagnosis"><span className="tag">CALIBRACIÓN REAL · {step+1} / 6</span><h2>Piensa antes<br/><em>de responder.</em></h2><p className="instruction">Escribe tu jugada en UCI —por ejemplo `e2e4`— o SAN —por ejemplo `Bxf7+`—. Tiempo transcurrido: {Math.round((Date.now()-started)/1000)}s.</p><div className="training-layout"><div className="board-wrap"><div className="real-board"><Chessboard animationDuration={250} position={current.presentedFen} arePiecesDraggable={false} boardWidth={Math.min(520,typeof window==='undefined'?520:window.innerWidth*0.48)} customDarkSquareStyle={{backgroundColor:'#668078'}} customLightSquareStyle={{backgroundColor:'#d9dfd5'}}/></div></div><div className="scan-panel"><span className="eyebrow">{current.themes[0]??'táctica'}</span><h3>{current.solutionUci.length>1?'Encuentra la mejor jugada':'Encuentra la jugada'}</h3><label className="peer-label" htmlFor="calibration-answer">TU RESPUESTA</label><input className="vision-input" id="calibration-answer" value={answer} onChange={event=>setAnswer(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')submit()}} placeholder="e2e4 o Bxf7+" autoFocus/><button className="primary full" onClick={submit}>Validar respuesta <span>→</span></button>{feedback&&<p className="board-message">{feedback}</p>}<div className="mate-progress">Aciertos: {correct} · rating provisional después de 6</div></div></div></div>}
function Vision(){const {recordVisionAttempt}=useStore(); const [time,setTime]=useState(60); const [score,setScore]=useState(0); const [question,setQuestion]=useState(0); const prompts=['Nombra una casilla clara del tablero.','¿Cuántas piezas atacan e4?','¿Esta jugada es legal?','¿Qué pieza da mate?']; const answers=['e4','2','sí','dama']; useEffect(()=>{const timer=window.setInterval(()=>setTime(value=>Math.max(0,value-1)),1000); return ()=>window.clearInterval(timer)},[]); const answer=(value:string)=>{const correct=value.toLowerCase().trim()===answers[question]; recordVisionAttempt(correct); if(correct)setScore(value=>value+1); setQuestion(value=>(value+1)%prompts.length)}; return <div className="page diagnosis"><span className="tag">DRILL DE VISIÓN · 60 SEGUNDOS</span><h2>Ver sin mover.<br/><em>Responder con precisión.</em></h2><div className="vision-header"><strong>{time}s</strong><span>{score} aciertos</span></div><div className="diagnosis-card"><div className="diagnosis-count"><strong>{question+1}</strong><span>/ 4 modos</span></div><div><span className="eyebrow">VISIÓN DE TABLERO</span><h3>{prompts[question]}</h3><input className="vision-input" aria-label="Respuesta del drill" placeholder="Escribe tu respuesta" onKeyDown={event=>{if(event.key==='Enter'){answer(event.currentTarget.value);event.currentTarget.value=''}}}/><p className="instruction">Pulsa Enter para responder. La precisión se guarda automáticamente.</p></div></div></div>}
function Mates(){const [theme,setTheme]=useState<MateTheme>('Pasillo'); const [index,setIndex]=useState(0); const [catalog,setCatalog]=useState<typeof mateLibrary>([]); useEffect(()=>{fetch('/data/mates/index.json').then(response=>response.json()).then(data=>setCatalog(data.puzzles)).catch(()=>setCatalog(mateLibrary))},[]); const current=catalog.find(item=>item.theme===theme&&item.index===index+1) ?? mateLibrary.find(item=>item.theme===theme&&item.index===index+1)!; return <div className="page train-page"><span className="tag">BIBLIOTECA DE MATES · 48 POSICIONES</span><h2>Reconoce el patrón.<br/><em>Encuentra el mate.</em></h2><div className="mate-tabs">{mateThemes.map(item=><button className={item===theme?'selected':''} onClick={()=>{setTheme(item);setIndex(0)}} key={item}>{item}</button>)}</div><div className="training-layout"><div className="board-wrap"><div className="real-board"><Chessboard animationDuration={250} position={current.fen} arePiecesDraggable={false} boardWidth={Math.min(620,typeof window==='undefined'?620:window.innerWidth*0.55)} customDarkSquareStyle={{backgroundColor:'#668078'}} customLightSquareStyle={{backgroundColor:'#d9dfd5'}}/></div><div className="board-caption"><span>{current.title}</span><span>{'sourceTheme' in current?String(current.sourceTheme):'local'} · sin red</span></div></div><div className="scan-panel"><span className="eyebrow">{theme.toUpperCase()}</span><h3>{current.prompt}</h3><p className="instruction">La posición viene de un tema etiquetado en Lichess. Estudia las casillas de escape y las piezas defensoras.</p><button className="primary full" onClick={()=>setIndex(value=>(value+1)%6)}>Siguiente posición <span>→</span></button><div className="mate-progress">{index+1} / 6 posiciones</div></div></div></div>}
function Openings(){const [rows,setRows]=useState<Opening[]>([]); const [query,setQuery]=useState(''); const {training}=useStore(); useEffect(()=>{loadOpenings().then(setRows)},[]); const results=searchOpenings(rows,query); const unlocked=openingsUnlocked(training); return <div className="page journal"><span className="tag">REPERTORIO · DATOS LOCALES</span><h2>{unlocked?'Explora tus':'Construye la base antes de'}<br/><em>{unlocked?'primeras aperturas.':'abrir repertorio.'}</em></h2><p className="instruction">{unlocked?'Base CC0 de Lichess. Búsqueda offline por ECO, nombre o secuencia PGN.':'Las aperturas se desbloquean con 20 partidas lentas y 90% en mate en uno.'}</p><div className="metrics"><Metric label="Partidas lentas" value={String(training.slowGames)} delta="objetivo 20" note="requeridas"/><Metric label="Mate en uno" value={`${training.mateInOne}%`} delta="objetivo 90%" note="requerido" good/></div>{unlocked&&<><input className="vision-input" aria-label="Buscar apertura" value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar Italiana, C20, Siciliana…"/><div className="opening-list">{results.map(row=><div className="journal-row" key={`${row.eco}-${row.name}`}><span className="journal-tag">{row.eco}</span><div><strong>{row.name}</strong><p>{row.pgn||'Secuencia no disponible'}</p></div></div>)}</div><small className="muted">{rows.length ? `${rows.length.toLocaleString()} aperturas cargadas` : 'Cargando base local…'}</small></>}</div>}
function OpeningsV2(){const [rows,setRows]=useState<Opening[]>([]);const [query,setQuery]=useState('');const [selected,setSelected]=useState<Opening|null>(null);const [repertoire,setRepertoire]=useState<string[]>(()=>JSON.parse(localStorage.getItem('godchess.repertoire')??'[]'));const {training}=useStore();const unlocked=openingsUnlocked(training);useEffect(()=>{loadOpenings().then(setRows)},[]);const results=searchOpenings(rows,query);const game=new Chess();if(selected?.pgn){try{game.loadPgn(selected.pgn)}catch{}}const toggle=()=>{if(!selected)return;const next=repertoire.includes(selected.eco+' '+selected.name)?repertoire.filter(item=>item!==selected.eco+' '+selected.name):[...repertoire,selected.eco+' '+selected.name];setRepertoire(next);localStorage.setItem('godchess.repertoire',JSON.stringify(next))};return <div className="page train-page"><span className="tag">REPERTORIO · LICHESS CC0 · OFFLINE</span><h2>Construye tu<br/><em>repertorio personal.</em></h2><p className="instruction">Selecciona cualquier apertura para estudiar su posición y línea PGN. Guardar en tu repertorio se desbloquea con 20 partidas lentas y 90% en mate en uno.</p><div className="metrics"><Metric label="Partidas lentas" value={String(training.slowGames)} delta="objetivo 20" note="requeridas"/><Metric label="Mate en uno" value={`${training.mateInOne}%`} delta="objetivo 90%" note="requerido" good/><Metric label="Mi repertorio" value={String(repertoire.length)} delta="local" note="aperturas guardadas"/></div><div className="opening-explorer"><div><input className="vision-input" aria-label="Buscar apertura" value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar Italiana, C20, Siciliana…"/><div className="opening-list">{results.map(row=><button className={'opening-choice '+(selected?.name===row.name?'selected':'')} onClick={()=>setSelected(row)} key={`${row.eco}-${row.name}`}><span className="journal-tag">{row.eco}</span><span><strong>{row.name}</strong><small>{row.pgn||'Secuencia no disponible'}</small></span></button>)}</div></div>{selected&&<div className="opening-detail"><div className="real-board"><Chessboard animationDuration={250} position={game.fen()} arePiecesDraggable={false} boardWidth={Math.min(470,typeof window==='undefined'?470:window.innerWidth*0.42)} customDarkSquareStyle={{backgroundColor:'#668078'}} customLightSquareStyle={{backgroundColor:'#d9dfd5'}}/></div><span className="eyebrow">{selected.eco} · LÍNEA PGN</span><p className="pgn-line">{selected.pgn||'Sin línea PGN'}</p><button className="primary full" disabled={!unlocked} onClick={toggle}>{repertoire.includes(selected.eco+' '+selected.name)?'Quitar del repertorio':'Guardar en mi repertorio'} <span>→</span></button></div>}</div></div>}
function Invite(){const [peerId,setPeerId]=useState(''); const [remoteId,setRemoteId]=useState(''); const [status,setStatus]=useState('Sin conexión'); const peer=useRef<Peer|null>(null); const connection=useRef<DataConnection|null>(null); useEffect(()=>()=>{peer.current?.destroy()},[]); const createInvite=()=>{const instance=new Peer({ ...localPeerConfig });peer.current=instance;setStatus('Creando invitación local…');instance.on('open',id=>{setPeerId(id);setStatus('Listo para compartir')});instance.on('connection',incoming=>{connection.current=incoming;incoming.on('open',()=>setStatus('Invitado conectado'))});instance.on('error',error=>setStatus(peerUnavailableMessage(error)))}; const join=()=>{if(!remoteId.trim())return; const instance=peer.current??new Peer({ ...localPeerConfig });peer.current=instance;instance.on('open',()=>{connection.current=instance.connect(remoteId.trim());connection.current.on('open',()=>setStatus('Conectado a la invitación'))});instance.on('error',error=>setStatus(peerUnavailableMessage(error)));setStatus('Conectando al PeerServer local…')}; return <div className="page journal"><span className="tag">PEERSERVER LOCAL · PEERJS</span><h2>Aprende con<br/><em>otra persona.</em></h2><p className="instruction">La señalización se ejecuta en localhost:9000. El servidor solo coordina el enlace; la partida viaja P2P entre los dispositivos.</p><div className="invite-panel"><span className="eyebrow">CREAR INVITACIÓN</span><h3>{status}</h3><button className="primary" onClick={createInvite}>Crear código <span>↗</span></button>{peerId&&<div className="peer-code"><label>CÓDIGO PARA COMPARTIR</label><code>{peerId}</code></div>}<label className="peer-label" htmlFor="peer-id">UNIRSE A UN CÓDIGO</label><input className="vision-input" id="peer-id" value={remoteId} onChange={event=>setRemoteId(event.target.value)} placeholder="Pega el código de tu invitado"/><button className="outline" onClick={join}>Conectar <span>→</span></button></div></div>}
function Train(){const {scans,setScan,resetScan,candidate,setCandidate,completeScan,training,recordPuzzleAttempt}=useStore(); const fallback=puzzleFor(); const [puzzle,setPuzzle]=useState<PreparedPuzzle|null>(null); const [solved,setSolved]=useState(false); const [cctValid,setCctValid]=useState(false); useEffect(()=>{loadPuzzleCatalog().then(catalog=>setPuzzle(chooseDuePuzzle(catalog,dueReviews(training.reviews).map(card=>card.puzzleId),'pieza',training.rating))).catch(()=>setPuzzle(null));},[training.rating]); const scanned=Object.values(scans).every(Boolean); const ready=scanned&&cctValid&&candidate.trim().length>1&&solved; const theme=puzzle?.themes[0] ?? fallback.theme; const prompt=puzzle?`Resuelve el motivo ${theme.replaceAll('_',' ')} en esta posición.`:fallback.prompt; const rating=puzzle?.rating ?? fallback.rating; return <div className="page train-page"><div className="train-top"><div><span className="tag">PASO 2 DE 4 · PUZZLE · {theme.toUpperCase()}</span><h2>Haz visible tu<br/><em>pensamiento.</em></h2><p>{prompt}</p></div><div className="timer">00:42<span>{puzzle?'catálogo local':'modo respaldo'}</span></div></div><div className="training-layout"><div className="board-wrap"><PuzzleBoard puzzle={puzzle} canMove={scanned} onSolved={()=>{setSolved(true);if(puzzle)recordPuzzleAttempt(true,puzzle.puzzleId,puzzle.rating,puzzle.solutionUci[0])}}/><div className="board-caption"><span>Posición {rating} · {scanned?'tablero desbloqueado':'escaneo obligatorio'}</span><span>{puzzle?'Lichess · índice local':'Puzzle de respaldo'}</span></div></div><div className="scan-panel"><span className="eyebrow">CHECK · CAPTURES · THREATS</span><h3>Escanea antes de mover</h3><p className="instruction">{puzzle?'La posición viene del catálogo Lichess local. Busca la jugada única después del escaneo.':`${fallback.hint1} ${fallback.hint2}`} El tablero permanece bloqueado hasta completar CCT.</p><CctInputs fen={puzzle?.presentedFen ?? fallback.fen} onValid={()=>setCctValid(true)}/>{[['checks','¿Qué jaques tengo?'],['captures','¿Qué capturas son posibles?'],['threats','¿Qué amenaza el rival?']].map(([key,label],i)=><button className={'scan-row '+(scans[key as keyof Scan]?'checked':'')} onClick={()=>setScan(key as keyof Scan)} key={key}><span className="check">{scans[key as keyof Scan]?'✓':i+1}</span><span>{label}</span><small>{scans[key as keyof Scan]?'listo':'marcar'}</small></button>)}<div className="candidate"><label htmlFor="candidate">TU JUGADA CANDIDATA <span>obligatoria</span></label><input id="candidate" value={candidate} onChange={e=>setCandidate(e.target.value)} placeholder="Escribe tras resolver el tablero"/><button className="primary full" disabled={!ready} onClick={completeScan}>{solved?'Registrar éxito':'Resuelve el puzzle'} <span>→</span></button></div><button className="reset" onClick={()=>{resetScan();setSolved(false);setCctValid(false)}}>Reiniciar escaneo</button></div></div></div>}
function PuzzleBoard({puzzle,canMove,onSolved}:{puzzle:PreparedPuzzle|null;canMove:boolean;onSolved:()=>void}){const [fen,setFen]=useState(puzzle?.presentedFen ?? 'start'); const [message,setMessage]=useState(''); const [solutionIndex,setSolutionIndex]=useState(0); const engine=useRef(new EngineClient()); const [engineReady,setEngineReady]=useState(false); useEffect(()=>{let mounted=true; engine.current.init().then(()=>{if(mounted){engine.current.setStrength(5,1320,200);setEngineReady(true)}}).catch(()=>setEngineReady(false)); return ()=>{mounted=false;engine.current.quit()}},[]); useEffect(()=>{setFen(puzzle?.presentedFen ?? 'start');setSolutionIndex(0);setMessage('')},[puzzle]); const drop=(source:string,target:string)=>{if(!canMove||!puzzle)return false; const before=fen; const game=new Chess(fen); const move=game.move({from:source,to:target,promotion:'q'}); if(!move)return false; const uci=source+target+(move.promotion??''); const expected=puzzle.solutionUci[solutionIndex]; if(uci!==expected){setMessage(engineReady?'Analizando la diferencia…':'Jugada legal, pero no es la solución.'); if(engineReady)void engine.current.bestMove(before,200).then(result=>setMessage(`No es la mejor: el motor propone ${result.bestMove}. Revisa tu candidata.`)); return true;} let nextIndex=solutionIndex+1; if(nextIndex<puzzle.solutionUci.length){const reply=puzzle.solutionUci[nextIndex];const replyMove=game.move({from:reply.slice(0,2),to:reply.slice(2,4),promotion:reply[4] as 'q'|'r'|'b'|'n'|undefined});if(replyMove)nextIndex++;} setFen(game.fen());setSolutionIndex(nextIndex);if(nextIndex>=puzzle.solutionUci.length){setMessage('Puzzle resuelto · secuencia completa');onSolved();}else setMessage('Correcto · continúa con la siguiente decisión');return true;}; return <div><HintPanel/><div className="real-board"><Chessboard animationDuration={250} position={fen} onPieceDrop={drop} arePiecesDraggable={canMove} boardWidth={Math.min(620, typeof window==='undefined'?620:window.innerWidth*0.55)} customDarkSquareStyle={{backgroundColor:'#668078'}} customLightSquareStyle={{backgroundColor:'#d9dfd5'}}/></div>{message ? <p className="board-message">{message}</p> : null}</div>}
function InviteV2(){const [peerId,setPeerId]=useState(''); const [remoteId,setRemoteId]=useState(''); const [status,setStatus]=useState('Sin conexión'); const [role,setRole]=useState<'w'|'b'|null>(null); const [fen,setFen]=useState(new Chess().fen()); const [clock,setClock]=useState({w:600000,b:600000}); const peer=useRef<Peer|null>(null); const connection=useRef<DataConnection|null>(null); const game=useRef(new Chess()); const startedAt=useRef(new Date().toISOString()); const record=(result:"white"|"black"|"draw"|"aborted",disconnect=false)=>saveGameRecord({id:`p2p-${startedAt.current}-${Math.random().toString(36).slice(2)}`,startedAt:startedAt.current,endedAt:new Date().toISOString(),pgn:game.current.pgn(),result,whiteMs:clock.w*1000,blackMs:clock.b*1000,finalFen:game.current.fen(),disconnect}); useEffect(()=>()=>peer.current?.destroy(),[]); useEffect(()=>{const timer=window.setInterval(()=>{if(connection.current && role && !game.current.isGameOver())setClock(value=>{const next=tickClock(value,game.current.turn(),1000);if(clockExpired(next))setStatus('Tiempo agotado');return next})},1000);return()=>window.clearInterval(timer)},[role]); const attach=(conn:DataConnection,side:'w'|'b')=>{connection.current=conn;setRole(side);conn.on('open',()=>{setStatus('Partida P2P conectada');conn.send({type:'state',fen:game.current.fen()})});conn.on('data',(data)=>{const packet=data as {type:string;uci?:string;fen?:string;whiteMs?:number;blackMs?:number};if(packet.type==='move'&&packet.uci){const move=game.current.move({from:packet.uci.slice(0,2),to:packet.uci.slice(2,4),promotion:packet.uci[4] as 'q'|'r'|'b'|'n'|undefined});if(move){setFen(game.current.fen());if(game.current.isGameOver())record(game.current.isCheckmate()?(game.current.turn()==='w'?'black':'white'):'draw')}}if(packet.whiteMs!==undefined&&packet.blackMs!==undefined)setClock({w:Math.max(0,packet.whiteMs),b:Math.max(0,packet.blackMs)});if(packet.type==='state'&&packet.fen){game.current=new Chess(packet.fen);setFen(packet.fen)}});conn.on('close',()=>{record('aborted',true);setStatus('La otra persona se desconectó')})}; const createInvite=()=>{const instance=new Peer({...localPeerConfig});peer.current=instance;setRole('w');setStatus('Creando invitación local…');instance.on('open',id=>{setPeerId(id);setStatus('Comparte el código para jugar con blancas')});instance.on('connection',conn=>attach(conn,'w'));instance.on('error',error=>setStatus(peerUnavailableMessage(error)))}; const join=()=>{if(!remoteId.trim())return;const instance=peer.current??new Peer({...localPeerConfig});peer.current=instance;instance.on('open',()=>attach(instance.connect(remoteId.trim()),'b'));instance.on('error',error=>setStatus(peerUnavailableMessage(error)));setStatus('Conectando al PeerServer local…')}; const drop=(source:string,target:string)=>{if(!role||game.current.turn()!==role)return false;const move=game.current.move({from:source,to:target,promotion:'q'});if(!move)return false;const uci=source+target+(move.promotion??'');setFen(game.current.fen());connection.current?.send({type:'move',uci,fen:game.current.fen(),whiteMs:clock.w,blackMs:clock.b});return true}; const reset=()=>{record('aborted');game.current.reset();setFen(game.current.fen());connection.current?.send({type:'state',fen:game.current.fen()})}; return <div className="page train-page"><span className="tag">PARTIDA P2P · PEERSERVER LOCAL</span><h2>Aprende con<br/><em>otra persona.</em></h2><p className="instruction">{status}. Blancas: anfitrión · negras: invitado.</p><div className="training-layout"><div className="board-wrap"><div className="real-board"><Chessboard animationDuration={250} position={fen} boardOrientation={role==='b'?'black':'white'} onPieceDrop={drop} arePiecesDraggable={Boolean(role&&connection.current&&game.current.turn()===role)} boardWidth={Math.min(620,typeof window==='undefined'?620:window.innerWidth*0.55)} customDarkSquareStyle={{backgroundColor:'#668078'}} customLightSquareStyle={{backgroundColor:'#d9dfd5'}}/></div><div className="board-caption"><span>{role==='w'?'Blancas':role==='b'?'Negras':'Sin color asignado'}</span><span>{formatClock(clock.w)} · {formatClock(clock.b)}</span></div></div><div className="scan-panel"><span className="eyebrow">INVITACIÓN LOCAL</span><h3>Conecta dos tableros</h3><button className="primary full" onClick={createInvite}>Crear código <span>↗</span></button>{peerId&&<div className="peer-code"><label>CÓDIGO PARA COMPARTIR</label><code>{peerId}</code></div>}<label className="peer-label" htmlFor="peer-id">UNIRSE COMO NEGRAS</label><input className="vision-input" id="peer-id" value={remoteId} onChange={event=>setRemoteId(event.target.value)} placeholder="Pega el código del anfitrión"/><button className="outline full" onClick={join}>Conectar <span>→</span></button><button className="reset" onClick={reset}>Reiniciar posición</button></div></div></div>}
function Play(){return <div className="page train-page"><div className="train-top"><div><span className="tag">PARTIDA LENTA · MOTOR LOCAL</span><h2>Juega con<br/><em>tiempo para pensar.</em></h2><p>El motor responde desde tu dispositivo y adapta su fuerza a tu rating interno.</p></div><div className="timer">10:00<span>por jugador</span></div></div><LocalGame/></div>}
function LocalGame(){const [fen,setFen]=useState(new Chess().fen()); const [status,setStatus]=useState('Tu turno · blancas'); const [thinking,setThinking]=useState(false); const [loss,setLoss]=useState(false); const [tag,setTag]=useState<ErrorTag|null>(null); const gameRef=useRef(new Chess()); const engine=useRef(new EngineClient()); const recordGameOutcome=useStore(s=>s.recordGameOutcome); useEffect(()=>{engine.current.init().then(()=>engine.current.setStrength(5,1320,300)).catch(()=>setStatus('Motor no disponible · modo local')); return ()=>engine.current.quit()},[]); const finishLoss=()=>{setLoss(true);setStatus('Partida terminada · etiqueta el error');}; const drop=(source:string,target:string)=>{if(thinking||loss)return false; const game=gameRef.current; const move=game.move({from:source,to:target,promotion:'q'}); if(!move)return false; setFen(game.fen()); if(game.isGameOver()){setStatus('Partida terminada');return true;} setThinking(true);setStatus('Stockfish está calculando…'); void engine.current.bestMove(game.fen(),300).then(result=>{const reply=game.move({from:result.bestMove.slice(0,2),to:result.bestMove.slice(2,4),promotion:result.bestMove[4] as 'q'|'r'|'b'|'n'|undefined}); if(reply)setFen(game.fen()); setThinking(false); if(game.isGameOver())finishLoss(); else setStatus(reply?'Tu turno · blancas':'Partida terminada');}).catch(()=>{setThinking(false);setStatus('Motor no disponible · tu turno');}); return true;}; const reset=()=>{gameRef.current.reset();setFen(gameRef.current.fen());setStatus('Tu turno · blancas');setThinking(false);setLoss(false);setTag(null);}; const saveTag=()=>{if(tag){recordGameOutcome(tag);setStatus('Partida guardada · siguiente foco actualizado');setLoss(false)}}; return <div className="training-layout"><div className="board-wrap"><div className="real-board"><Chessboard animationDuration={250} position={fen} onPieceDrop={drop} arePiecesDraggable={!thinking&&!loss} boardWidth={Math.min(620,typeof window==='undefined'?620:window.innerWidth*0.55)} boardOrientation="white" customDarkSquareStyle={{backgroundColor:'#668078'}} customLightSquareStyle={{backgroundColor:'#d9dfd5'}}/></div><div className="board-caption"><span>{status}</span><span>sin red · Worker activo</span></div></div><div className="scan-panel"><span className="eyebrow">PARTIDA LENTA</span><h3>{thinking?'Analizando tu jugada':loss?'Cierre obligatorio':'Tu turno'}</h3>{loss?<><p className="instruction">¿Qué causó la derrota? Elige una causa para actualizar tu plan.</p><div className="error-tags">{(['pieza colgada','amenaza no vista','mate fallado','cambio mal calculado','rey expuesto','apuro de tiempo','otro'] as ErrorTag[]).map(item=><button className={tag===item?'selected':''} onClick={()=>setTag(item)} key={item}>{item}</button>)}</div><button className="primary full" disabled={!tag} onClick={saveTag}>Guardar etiqueta <span>→</span></button></>:<><p className="instruction">Busca jaques, capturas y amenazas antes de mover. El motor juega con fuerza adaptada.</p><div className="focus-line"><div className="focus-icon">♞</div><div><strong>Stockfish 17.1</strong><p>Single-thread · 300 ms</p></div></div></>}<button className="outline full" onClick={reset}>Nueva partida <span>↻</span></button></div></div>}
function Journal(){return <div className="journal"><div className="section-head"><div><span className="eyebrow">REGISTRO PERSISTENTE</span><h2>Diario de errores</h2></div><button className="outline">Exportar datos ↗</button></div>{['Hoy · Drill de visión','Ayer · Partida lenta #006','23 nov · Partida rápida #005'].map((x,i)=><div className="journal-row" key={x}><div className="journal-date">{i===0?'26':'2'+(5-i)}<small>NOV</small></div><div><strong>{x}</strong><p>{i===0?'Precisión 74% · 42 segundos':'Pieza colgada en jugada '+(18+i*3)+' · FEN guardado'}</p></div><span className="journal-tag">{i===0?'visión':'pieza colgada'}</span></div>)}</div>}
function GameHistory(){const records=loadGameRecords();return <div className="journal game-history"><div className="section-head"><div><span className="eyebrow">PARTIDAS LOCALES</span><h2>Historial P2P</h2></div><span className="range">{records.length} guardadas</span></div>{records.length?records.map(record=><div className="journal-row" key={record.id}><div className="journal-date">{record.result}<small>{record.disconnect?'corte':'PGN'}</small></div><div><strong>{new Date(record.endedAt).toLocaleString()}</strong><p>{record.pgn||'Sin movimientos'} · FEN guardada</p></div><span className="journal-tag">{record.result}</span></div>):<p className="instruction">Todavía no hay partidas locales guardadas.</p>}</div>}
function JournalFull(){return <><Journal/><GameHistory/></>}
function GuidedLesson(){const {lessonId,setTab,openLesson}=useStore();const unit=trainingPath.find(item=>item.id===lessonId)??trainingPath[0];const pieces:Record<string,{type:string;fen:string;rule:string}>={pawn:{type:'p',fen:'7k/8/8/3p4/4P3/8/8/7K w - - 0 1',rule:'Avanza hacia delante y captura en diagonal.'},rook:{type:'r',fen:'7k/8/8/3R4/8/8/8/7K w - - 0 1',rule:'Recorre líneas rectas hasta encontrar un obstáculo.'},bishop:{type:'b',fen:'7k/8/8/3B4/8/8/8/7K w - - 0 1',rule:'Recorre diagonales del mismo color.'},knight:{type:'n',fen:'7k/8/8/3N4/8/8/8/7K w - - 0 1',rule:'Salta en forma de L y supera piezas.'},queen:{type:'q',fen:'7k/8/8/3Q4/8/8/8/7K w - - 0 1',rule:'Combina líneas rectas y diagonales.'},king:{type:'k',fen:'k7/8/8/8/8/8/8/4K3 w - - 0 1',rule:'Se mueve una casilla y nunca entra en jaque.'}};const lesson=pieces[unit.id];const guided=Boolean(lesson)||unit.id==="board";const [position,setPosition]=useState(lesson?.fen??'start');const [selected,setSelected]=useState<string|null>(null);const [targets,setTargets]=useState<string[]>([]);const [message,setMessage]=useState(lesson?'Selecciona la pieza para ver sus movimientos.':'Observa la posición y después pasa al ejercicio.');useEffect(()=>{const nextFen=lesson?.fen??'start';setPosition(nextFen);if(lesson){const game=new Chess(nextFen);const square=game.board().flat().findIndex(piece=>piece?.type===lesson.type && piece.color==='w');const file=square%8;const rank=7-Math.floor(square/8);const selectedSquare=square>=0?String.fromCharCode(97+file)+(rank+1):null;const moves=selectedSquare?(game.moves({square:selectedSquare as never,verbose:true}) as Array<{to:string}>).map(move=>move.to):[];setSelected(selectedSquare);setTargets(moves);setMessage(selectedSquare?'Las casillas verdes muestran cómo se mueve.':'Selecciona la pieza para ver sus movimientos.')}else{setSelected(null);setTargets([]);setMessage('Observa la posición y después pasa al ejercicio.')}},[lessonId]);const reset=()=>{setPosition(lesson?.fen??'start');setSelected(null);setTargets([])};const click=(square:string)=>{if(!lesson)return;const game=new Chess(position);if(!selected){const current=game.get(square as never);if(!current||current.type!==lesson.type)return;const moves=game.moves({square:square as never,verbose:true}) as Array<{to:string}>;setSelected(square);setTargets(moves.map(move=>move.to));setMessage('Elige una casilla resaltada.');return}if(square===selected){setMessage("Pieza seleccionada. Elige una casilla verde.");return}if(targets.includes(square)){game.move({from:selected,to:square,promotion:'q'});setPosition(game.fen());setMessage(`Movimiento correcto. Observa la animación hasta ${square}.`);window.setTimeout(reset,1100)}else setMessage('Esa casilla no es legal para esta pieza.')};const styles:Record<string,object>={};if(selected)styles[selected]={backgroundColor:'rgba(215,255,100,.65)'};targets.forEach(square=>{styles[square]={backgroundColor:'rgba(126,219,197,.7)'}});const next=()=>{if(guided){const index=trainingPath.findIndex(item=>item.id===unit.id);const following=trainingPath[index+1];if(following){openLesson(following.id);return}}setTab(unit.kind==='opening'?'openings':unit.kind==='game'?'play':'train')};return <div className="page lesson-page"><span className="tag">LECCIÓN · FASE {unit.phase}</span><h2>{unit.title}<br/><em>aprende haciendo.</em></h2><p className="instruction">{unit.description}</p><button className="primary lesson-top-action" onClick={next}>{guided?"Siguiente lección":"Practicar ahora"} <span>→</span></button><div className="lesson-layout"><div className="real-board lesson-board"><Chessboard animationDuration={420} position={position} onSquareClick={click} arePiecesDraggable={false} customSquareStyles={styles} customArrows={(selected?targets.map(to=>[selected,to,"#d7ff64"]):[]) as never} boardWidth={Math.min(520,typeof window==='undefined'?520:window.innerWidth*.48)} customDarkSquareStyle={{backgroundColor:'#668078'}} customLightSquareStyle={{backgroundColor:'#d9dfd5'}}/><p className="board-message">{message}</p></div><div className="diagnosis-card lesson-card"><div className="diagnosis-count"><strong>1</strong><span>/ 3</span></div><div><span className="eyebrow">{guided?'MOVIMIENTO GUIADO':'CONCEPTO CLAVE'}</span><h3>{guided?'Selecciona, observa y mueve':'Observa, nombra y después prueba'}</h3><p className="instruction">{guided?'Las casillas verdes muestran los movimientos legales. Haz una jugada y la posición se reinicia para practicar otra ruta.':'Esta lección prepara el ejercicio dirigido que viene a continuación.'}</p>{lesson&&<p className="instruction"><strong>Regla:</strong> {lesson.rule}</p>}</div></div></div><button className="primary lesson-bottom-action" onClick={next}>{guided?'Siguiente lección':'Practicar ahora'} <span>→</span></button></div>}
function Studio(){const [fen,setFen]=useState(()=>localStorage.getItem('godchess.study.fen')??new Chess().fen());const [pgn,setPgn]=useState(()=>localStorage.getItem('godchess.study.pgn')??'');const [analysis,setAnalysis]=useState('Motor listo · analiza esta posición localmente.');const [saved,setSaved]=useState<string[]>(()=>JSON.parse(localStorage.getItem('godchess.study.saved')??'[]'));const engine=useRef(new EngineClient());useEffect(()=>{void engine.current.init().catch(()=>setAnalysis('Motor no disponible · el estudio sigue funcionando offline.'));return()=>engine.current.quit()},[]);const loadFen=(value:string)=>{try{const game=new Chess(value.trim()||undefined);setFen(game.fen());setAnalysis('FEN válido · listo para analizar.')}catch{setAnalysis('FEN no válido. Comprueba las seis partes de la posición.')}};const analyze=async()=>{try{setAnalysis('Stockfish analiza en Worker…');const result=await engine.current.analyze(fen,16);setAnalysis(`Evaluación ${result.score?.cp??(result.score?.mate?`mate en ${result.score.mate}`:'—')} · PV ${result.pv?.slice(0,8).join(' ')??'sin variante'}`)}catch{setAnalysis('No se pudo analizar esta posición.')}};const save=()=>{const next=[fen,...saved.filter(item=>item!==fen)].slice(0,20);setSaved(next);localStorage.setItem('godchess.study.saved',JSON.stringify(next));localStorage.setItem('godchess.study.fen',fen);localStorage.setItem('godchess.study.pgn',pgn);setAnalysis('Posición guardada localmente.');};return <div className="page train-page"><span className="tag">ESTUDIO LOCAL · PGN · STOCKFISH</span><h2>Analiza sin salir<br/><em>de tu tablero.</em></h2><p className="instruction">Importa una posición FEN, conserva una línea PGN y analiza con Stockfish en un Worker. Nada sale del dispositivo.</p><div className="training-layout"><div className="board-wrap"><div className="real-board"><Chessboard position={fen} arePiecesDraggable={false} boardWidth={Math.min(620,typeof window==='undefined'?620:window.innerWidth*.55)} boardOrientation="white"/></div><p className="board-message">{analysis}</p></div><div className="scan-panel"><span className="eyebrow">ANÁLISIS LOCAL</span><h3>Posición y variante</h3><label className="peer-label" htmlFor="study-fen">FEN</label><input className="vision-input" id="study-fen" value={fen} onChange={event=>setFen(event.target.value)} onBlur={event=>loadFen(event.target.value)}/><label className="peer-label" htmlFor="study-pgn">PGN / NOTAS</label><textarea className="vision-input" id="study-pgn" value={pgn} onChange={event=>setPgn(event.target.value)} rows={5} placeholder="1. e4 e5 2. Cf3…"/><button className="primary full" onClick={()=>void analyze()}>Analizar con Stockfish <span>↗</span></button><button className="outline full" onClick={save}>Guardar posición <span>＋</span></button><div className="study-saved"><span className="eyebrow">POSICIONES GUARDADAS · {saved.length}</span>{saved.slice(0,3).map(item=><button className="opening-choice" key={item} onClick={()=>setFen(item)}>{item}</button>)}</div></div></div></div>}
function Metric({label,value,delta,note,good}:{label:string,value:string,delta:string,note:string,good?:boolean}){return <div className="metric"><span>{label}</span><strong>{value}</strong><div><b className={good?'good':''}>{delta}</b><small>{note}</small></div></div>}
const rootHost = document.getElementById('root')!;
const runtime = globalThis as typeof globalThis & { __godChessRoot?: ReturnType<typeof createRoot> };
const appRoot = runtime.__godChessRoot ?? createRoot(rootHost);
runtime.__godChessRoot = appRoot;
appRoot.render(<React.StrictMode><App/></React.StrictMode>);
